// ==============================================================================
// GTF Student Signup Normalization & WhatsApp Onboarding Message Formatter
// ==============================================================================
const raw = $input.first().json.body || $input.first().json || {};

// 1. Extract and Clean Student Identity
const fullName = (raw.fullName || raw.displayName || raw.name || 'GTF Student').trim();
const email = (raw.email || raw.userEmail || '').toLowerCase().trim();
const rawPhone = String(raw.phone || raw.phoneNumber || raw.whatsapp || '+4917660720947').trim();
const cleanPhone = rawPhone.replace(/[^0-9]/g, '');
const whatsappE164 = cleanPhone.startsWith('+') ? cleanPhone : (cleanPhone.length === 10 ? `91${cleanPhone}` : cleanPhone);

// 2. Target Level & Program
const rawCourse = (raw.course || raw.targetLevel || raw.level || 'A1').toUpperCase().trim();
const course = ['A1', 'A2', 'B1', 'B2', 'STUDIENKOLLEG', 'PFLEGE'].includes(rawCourse) ? rawCourse : 'A1';

// 3. Generate Valid GTF Student ID (GTF-YYYY-XXXX format)
const year = new Date().getFullYear();
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const studentId = raw.studentId && /^GTF-[0-9]{4}-[A-Za-z0-9]{4}$/.test(raw.studentId)
  ? raw.studentId
  : `GTF-${year}-${randomSuffix}`;

// 4. Portal Credentials & Direct Links
const portalUrl = 'https://app.gatewaytofuture.com';
const dashboardLink = `${portalUrl}/dashboard?email=${encodeURIComponent(email)}`;
const academyLink = `${portalUrl}/academy/${course.toLowerCase()}`;
const loginPasscode = raw.loginPassword || `GTF-${email.split('@')[0].slice(0, 5).toUpperCase()}-2026`;
const nowIso = new Date().toISOString();

// 5. Construct Founder & CEO-Led Trilingual WhatsApp Onboarding Message
const whatsappMessage = `*Herzlich willkommen bei The Gateway to Future (GTF) Berlin!* 🇩🇪🇮🇳\n\nGuten Tag *${fullName}*,\n\nAapka German *${course}* Learning & Relocation Portal officially activate ho chuka hai! Berlin HQ se Sarbjit Kour (Founder & CEO, Gateway To Future) aapka swagat karti hain.\n\n━━━━━━━━━━━━━━━━━━━━\n🎓 *AAPKE GTF PORTAL LOGIN CREDENTIALS:*\n• *Student ID:* \`${studentId}\`\n• *Registered Email:* ${email}\n• *Access Passcode:* \`${loginPasscode}\`\n• *Direct Dashboard Link:* ${dashboardLink}\n• *Your Course Hub:* ${academyLink}\n━━━━━━━━━━━━━━━━━━━━\n\n🚀 *WHAT TO DO IN YOUR FIRST 24 HOURS:*\n1. *Vocabulary Decks & Flashcards:* Daily 10 cards drill karein (with native studio audio + Hindi memory tricks).\n2. *122 Säulen Grammar Dossiers:* Open Subdivision 02 for structured rulebooks.\n3. *Hören & Lesen Labs:* 40 interactive Goethe/telc style labs with instant Musterlösung.\n4. *7 Proprietary Workbooks:* Download your official workbook suite from the portal.\n\n📞 *FOUNDER & CEO SUPPORT:*\nAgar aapko course, blocked account (Sperrkonto), visa checklist, ya hospital/university placement mein koi bhi sawal ho, toh seedha Berlin HQ (+49 152 28372894) par WhatsApp message bhej sakte hain.\n\nWir wünschen Ihnen viel Erfolg bei Ihrer Vorbereitung!\n\n*Sarbjit Kour (Founder & CEO, Gateway To Future)*\nThe Gateway to Future (GTF)\n_Schönefelder Straße 2, GStU, 12355 Berlin, Germany_\nwww.gatewaytofuture.com`;

return [
  {
    json: {
      studentId,
      email,
      fullName,
      phone: rawPhone,
      whatsappE164,
      course,
      role: 'student',
      registeredAt: nowIso,
      updatedAt: nowIso,
      loginPasscode,
      dashboardLink,
      whatsappMessage,
      onboardingStatus: 'READY_TO_DISPATCH'
    }
  }
];
